From 361f2a22f5e25228fb4e2c40c291414e0d9b60ff Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 19:45:23 +0100
Subject: [PATCH] applets/notifications: Remember the job details expansion
 state

Every new transfer notification started with Details collapsed, so users
watching speed or remaining files had to expand it every time. Save the
last Details choice as applet state and use it for each new job view.

BUG: 522935
---
 applets/notifications/components/JobItem.qml | 14 ++++++++++++-
 applets/notifications/notificationapplet.cpp | 21 ++++++++++++++++++++
 applets/notifications/notificationapplet.h   | 17 ++++++++++++++++
 3 files changed, 51 insertions(+), 1 deletion(-)

diff --git a/applets/notifications/components/JobItem.qml b/applets/notifications/components/JobItem.qml
index 3e0efe8c39..466db2e26c 100644
--- a/applets/notifications/components/JobItem.qml
+++ b/applets/notifications/components/JobItem.qml
@@ -23,6 +23,11 @@ ColumnLayout {

     property ModelInterface modelInterface

+    property bool detailsExpanded: false
+
+    // Keep existing views independent of choices made in concurrent transfers.
+    Component.onCompleted: detailsExpanded = Notifications.JobDetailsState.expanded()
+
     readonly property int totalFiles: modelInterface.jobDetails && modelInterface.jobDetails.totalFiles || 0

     readonly property alias menuOpen: otherFileActionsMenu.visible
@@ -56,9 +61,16 @@ ColumnLayout {
             icon.name: checked ? "collapse-symbolic" : "expand-symbolic"
             text: i18ndc("plasma_applet_org.kde.plasma.notifications", "Hides/expands item details", "Details")
             checkable: jobItem.modelInterface.jobDetails && jobItem.modelInterface.jobDetails.hasDetails
+            checked: checkable && jobItem.detailsExpanded
             visible: checkable

-            Accessible.onPressAction: if (checkable) toggle()
+            onToggled: {
+                jobItem.detailsExpanded = checked;
+                Notifications.JobDetailsState.rememberExpanded(checked);
+            }
+
+            Accessible.onPressAction: if (visible && checkable) click()
+            Accessible.onToggleAction: if (visible && checkable) click()
         }

         Item { Layout.fillWidth: true }
diff --git a/applets/notifications/notificationapplet.cpp b/applets/notifications/notificationapplet.cpp
index 579dd0d790..4d0957dfd6 100644
--- a/applets/notifications/notificationapplet.cpp
+++ b/applets/notifications/notificationapplet.cpp
@@ -6,6 +6,8 @@

 #include "notificationapplet.h"

+#include <KSharedConfig>
+
 #include <QGuiApplication>
 #include <QJSEngine>
 #include <QJSValue>
@@ -27,6 +29,25 @@ void InputDisabler::makeTransparentForInput(QQuickItem *item)
     }
 }

+JobDetailsState::JobDetailsState(QObject *parent)
+    : QObject(parent)
+    , m_state(KSharedConfig::openStateConfig(QStringLiteral("plasmanotificationsstaterc"))->group(QStringLiteral("Jobs")))
+{
+}
+
+bool JobDetailsState::expanded() const
+{
+    return m_state.readEntry("DetailsExpanded", false);
+}
+
+void JobDetailsState::rememberExpanded(bool expanded)
+{
+    if (this->expanded() != expanded) {
+        m_state.writeEntry("DetailsExpanded", expanded);
+        m_state.sync();
+    }
+}
+
 NotificationApplet::NotificationApplet(QObject *parent, const KPluginMetaData &data, const QVariantList &args)
     : Plasma::Applet(parent, data, args)
 {
diff --git a/applets/notifications/notificationapplet.h b/applets/notifications/notificationapplet.h
index 0f7cc69433..e3d9d4760b 100644
--- a/applets/notifications/notificationapplet.h
+++ b/applets/notifications/notificationapplet.h
@@ -9,6 +9,8 @@
 #include <QQuickItem>
 #include <QWindow>

+#include <KConfigGroup>
+
 #include <Plasma/Applet>

 class QRect;
@@ -23,6 +25,21 @@ public:
     Q_INVOKABLE void makeTransparentForInput(QQuickItem *item);
 };

+class JobDetailsState : public QObject
+{
+    Q_OBJECT
+    QML_ELEMENT
+    QML_SINGLETON
+
+public:
+    explicit JobDetailsState(QObject *parent = nullptr);
+    Q_INVOKABLE bool expanded() const;
+    Q_INVOKABLE void rememberExpanded(bool expanded);
+
+private:
+    KConfigGroup m_state;
+};
+
 class NotificationApplet : public Plasma::Applet
 {
     Q_OBJECT
-- 
